323	    10	/**
324	    11	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
325	    12	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
326	    13	 * (half-even) at every step.
327	    14	 */
328	    15	public final class PriceCalculator {
329	    16	
330	    17	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
331	    18	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
332	    19	
333	    20	    /** Easter week, from Palm Sunday to Easter Sunday (both nights included). */
334	    21	    private static final List<DateRange> EASTER_WEEKS = List.of(
335	    22	            new DateRange(LocalDate.of(2027, 3, 21), LocalDate.of(2027, 3, 28)),
336	    23	            new DateRange(LocalDate.of(2028, 4, 9), LocalDate.of(2028, 4, 16)));
337	    24	
338	    25	    private record DateRange(LocalDate first, LocalDate last) {
339	    26	        boolean contains(LocalDate date) {
340	    27	            return !date.isBefore(first) && !date.isAfter(last);
341	    28	        }
342	    29	    }
343	    30	
344	    31	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
345	    32	        int nights = 0;
346	    33	        BigDecimal subtotal = cents(BigDecimal.ZERO);
347	    34	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
348	    35	            subtotal = subtotal.add(nightPrice(room, night));
349	    36	            nights++;
350	    37	        }
351	    38	        BigDecimal discount = switch (ratePlan) {
352	    39	            case STANDARD -> cents(BigDecimal.ZERO);
353	    40	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
354	    41	        };
355	    42	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
356	    43	    }
357	    44	
358	    45	    BigDecimal nightPrice(Room room, LocalDate night) {
359	    46	        BigDecimal nightlyRate = room.nightlyRate();
360	    47	        if (isHighSeason(night)) {
361	    48	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
362	    49	        }
363	    50	        return cents(nightlyRate);
364	    51	    }
365	    52	
366	    53	    /** High season: from December 15 to the end of February, the whole of July, and Easter week. */
367	    54	    static boolean isHighSeason(LocalDate date) {
368	    55	        Month month = date.getMonth();
369	    56	        return month == Month.JANUARY
370	    57	                || month == Month.FEBRUARY
371	    58	                || month == Month.JULY
372	    59	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15)
373	    60	                || EASTER_WEEKS.stream().anyMatch(week -> week.contains(date));
374	    61	    }
375	    62	
376	    63	    static BigDecimal cents(BigDecimal value) {
377	    64	        return value.setScale(2, RoundingMode.HALF_EVEN);
378	    65	    }
379	    66	}
